fenceColumns = [['.', '.', '#', '.'], ['#', '.', '#', '#'], ['.', '.', '.', '.']]
bestMissing = 5
for column in fenceColumns:
    missingCount = 0
    for cell in column:
        if cell == '.':
            missingCount = missingCount + 1
    if missingCount < bestMissing:
        bestMissing = missingCount
