w4-building-fences:
dimensions = input().split()
rowCount = int(dimensions[0])
columnCount = int(dimensions[1])
fieldRows = []
for rowIndex in range(rowCount):
    fieldRows.append(input())
bestMissing = rowCount + 1
for columnIndex in range(columnCount):
    missingCount = 0
    for rowIndex in range(rowCount):
        if fieldRows[rowIndex][columnIndex] == '.':
            missingCount = missingCount + 1
    if missingCount < bestMissing:
        bestMissing = missingCount
print(bestMissing)

